function Get-OpenAzureSqlFirewallRules {
    param([string]$SubscriptionId)
    if ($SubscriptionId) { Set-AzContext -SubscriptionId $SubscriptionId | Out-Null }
    $servers = Get-AzSqlServer
    foreach ($server in $servers) {
        try {
            $rules = Get-AzSqlServerFirewallRule -ServerName $server.ServerName -ResourceGroupName $server.ResourceGroupName
            foreach ($rule in $rules) {
                if ($rule.StartIpAddress -ne $rule.EndIpAddress) {
                    [PSCustomObject]@{
                        ServerName = $server.ServerName
                        RuleName   = $rule.FirewallRuleName
                        StartIp    = $rule.StartIpAddress
                        EndIp      = $rule.EndIpAddress
                    }
                }
            }
        } catch {
            Write-Warning "Failed to read rules for $($server.ServerName): $_"
        }
    }
}

